prop circle_inscribed_in_triangle(a, b, c, center cart(R, R), radius R+):
    $f6::is_in_triangle_interior(center, a, b, c)
    exist first, second, third cart(R, R) st {$f5::is_on_segment(first, a, b), $f5::is_on_segment(second, b, c), $f5::is_on_segment(third, c, a), $f7::is_tangent_line_at(first, a, b, center, radius), $f7::is_tangent_line_at(second, b, c, center, radius), $f7::is_tangent_line_at(third, c, a, center, radius)}
